import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.CfwCq2QB.js";const n="/dev-go-docs/shots/0.2.3/en/light/composite-popup-tabs.png",s="/dev-go-docs/shots/0.2.5/en/light/popup-function.png",f=JSON.parse('{"title":"What is DevGo","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/index.md","filePath":"en/guide/index.md"}'),i={name:"en/guide/index.md"};function d(l,e,h,c,g,p){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="what-is-devgo" tabindex="-1">What is DevGo <a class="header-anchor" href="#what-is-devgo" aria-label="Permalink to &quot;What is DevGo&quot;">​</a></h1><p>DevGo is a browser extension built for developers: translation, an AI assistant, proxy management with real IP protection, and media sniffing — all in one extension that speaks both Chinese and English, on Chrome and Firefox.</p><p>Instead of installing five extensions that each do one thing, DevGo aims to make every feature stand on its own while sharing the same config and interaction language.</p><h2 id="what-it-can-do" tabindex="-1">What it can do <a class="header-anchor" href="#what-it-can-do" aria-label="Permalink to &quot;What it can do&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>In one sentence</th><th>Docs</th></tr></thead><tbody><tr><td>Full-page bilingual translation</td><td>Translations follow the original paragraphs; Shadow DOM pages supported</td><td><a href="/dev-go-docs/en/features/page-translate.html">Full-page bilingual translation</a></td></tr><tr><td>Selection toolbar</td><td>Translate, explain, or summarize any text you select — with custom AI actions</td><td><a href="/dev-go-docs/en/features/selection-toolbar.html">Selection toolbar</a></td></tr><tr><td>AI assistant</td><td>Summarize the page and ask questions about it, in a side panel</td><td><a href="/dev-go-docs/en/features/assistant.html">AI assistant</a></td></tr><tr><td>Page tools (WebMCP)</td><td>The AI can call tools registered by the page and act on it for you</td><td><a href="/dev-go-docs/en/features/webmcp.html">Page tools (WebMCP)</a></td></tr><tr><td>Site tools &amp; recording</td><td>Add AI-callable tools to any site: let the AI build them or record your actions</td><td><a href="/dev-go-docs/en/features/site-tools.html">Site tools &amp; recording</a></td></tr><tr><td>Page export</td><td>Export the page as a PDF / long image that matches the screen, or just a selected area</td><td><a href="/dev-go-docs/en/features/capture.html">Page export</a></td></tr><tr><td>Proxy &amp; rule-based routing</td><td>Four network modes, one click to switch; rules route traffic automatically</td><td><a href="/dev-go-docs/en/features/proxy.html">Proxy &amp; rule-based routing</a></td></tr><tr><td>Real IP protection</td><td>Stop sites from using WebRTC to grab your real IP while you&#39;re on a proxy</td><td><a href="/dev-go-docs/en/features/ip-protection.html">Real IP protection</a></td></tr><tr><td>Media sniffer</td><td>Sniff images, videos, and audio on the current tab; download in bulk</td><td><a href="/dev-go-docs/en/features/media-sniffer.html">Media sniffer</a></td></tr><tr><td>Floating dock</td><td>Quick actions on the right edge of every page</td><td><a href="/dev-go-docs/en/features/dock.html">Floating dock</a></td></tr><tr><td>New tab</td><td>Search engines with bang syntax, quick links, dynamic backgrounds</td><td><a href="/dev-go-docs/en/features/newtab.html">New tab</a></td></tr><tr><td>Page enhancements</td><td>Per-site copy unlocking and GitHub enhancements</td><td><a href="/dev-go-docs/en/features/page-enhance.html">Page enhancements</a></td></tr></tbody></table><h2 id="the-interface-in-30-seconds" tabindex="-1">The interface in 30 seconds <a class="header-anchor" href="#the-interface-in-30-seconds" aria-label="Permalink to &quot;The interface in 30 seconds&quot;">​</a></h2><p>DevGo&#39;s day-to-day controls live in three places:</p><ul><li><strong>The popup</strong>: click the toolbar icon (or press <code>Alt+1</code>). Four pages — Translate, Network, Resources, Features — hold only the high-frequency actions for the current page.</li><li><strong>The side panel</strong>: press <code>Alt+2</code> for the AI assistant — summarize pages, ask about their content.</li><li><strong>Settings</strong>: everything is configured here, organized into Translation / AI models / Selection / AI assistant / Network / Page enhancements / General.</li></ul><img src="'+n+'" alt="The popup&#39;s four pages side by side: Translate, Network, Resources, Features"><p><em>The popup&#39;s four pages — Translate, Network, Resources, Features — in one view.</em></p><img src="'+s+'" alt="Overview: the popup&#39;s Features page" style="width:60%;display:block;margin-left:auto;margin-right:auto;"><p><em>The popup&#39;s Features page: AI assistant, page tools, recording and page export, plus per-site switches for the selection toolbar, floating dock, and copy unlocking.</em></p><p>After <a href="/dev-go-docs/en/guide/install.html">installing</a>, walk through the <a href="/dev-go-docs/en/guide/quick-start.html">Quick start (5 minutes)</a>.</p><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;Links&quot;">​</a></h2><ul><li><a href="https://chrome.google.com/webstore/detail/devgo/kcofdbjhicjdbmldlcffcijglkifnnjn" target="_blank" rel="noreferrer">Chrome Web Store</a></li><li><a href="https://github.com/fedtop/DevGo" target="_blank" rel="noreferrer">GitHub repository</a></li><li><a href="https://github.com/fedtop/DevGo/releases" target="_blank" rel="noreferrer">Offline builds on GitHub Releases</a></li></ul>',15)])])}const m=t(i,[["render",d]]);export{f as __pageData,m as default};
